"""Read-only visual QA of synthetic PDFs generated by workout-documents.test.ts.
Requires local Poppler + Pillow; never imported by the application.
"""
import json
import pathlib
import subprocess
import xml.etree.ElementTree as ET
from PIL import Image, ImageDraw
root = pathlib.Path('test-results/011/pdf')
root.mkdir(parents=True, exist_ok=True)
report = {}
for file in sorted(pathlib.Path('output/pdf').glob('011-*.pdf')):
    name = file.stem[4:]
    out = root / name
    out.mkdir(exist_ok=True)
    for old in out.glob('page-*.png'):
        old.unlink()
    subprocess.run(['pdftoppm', '-scale-to', '1200', '-png', str(file), str(out / 'page')], check=True)
    bbox = subprocess.check_output(['pdftotext', '-bbox', str(file), '-'])
    xml = ET.fromstring(bbox)
    ns = {'h': 'http://www.w3.org/1999/xhtml'}
    for page in xml.findall('.//h:page', ns):
        assert 595 < float(page.attrib['width']) < 596
        assert 841 < float(page.attrib['height']) < 843
        for word in page.findall('.//h:word', ns):
            box = word.attrib
            assert float(box['xMin']) >= 41 and float(box['xMax']) <= 555, (name, word.text, box)
            assert float(box['yMin']) >= 29 and float(box['yMax']) <= 821, (name, word.text, box)
    pages = sorted(out.glob('page-*.png'))
    count = len(pages)
    chosen = sorted({0, count // 2, count - 1})
    report[name] = {'pages': count, 'bytes': file.stat().st_size, 'review': [i + 1 for i in chosen]}
    # All pages, including those between the required first/middle/last samples.
    for batch in range(0, count, 6):
        indices = list(range(batch, min(batch + 6, count)))
        sheet = Image.new('RGB', (420 * min(3, len(indices)), 630 * ((len(indices) + 2) // 3)), '#dedede')
        draw = ImageDraw.Draw(sheet)
        for pos, i in enumerate(indices):
            im = Image.open(pages[i])
            im.thumbnail((410, 595))
            x, y = (pos % 3) * 420, (pos // 3) * 630
            sheet.paste(im, (x + 5, y + 24))
            draw.text((x + 10, y + 5), f'{name} / {i + 1} de {count}', fill='black')
        sheet.save(root / f'{name}-all-{batch // 6 + 1}.png')
(root / 'manifest.json').write_text(json.dumps(report, indent=2))
print(json.dumps(report))
